    $paymentTone = match($order->payment_status) { 'paid' => 'bg-brand-50 text-brand-800', 'failed' => 'bg-red-50 text-red-700', 'refunded' => 'bg-violet-50 text-violet-700', default => 'bg-stone-100 text-stone-600' };
    $staffRole = auth()->user()->is_admin && in_array(auth()->user()->role, [null,'customer','administrator'], true) ? 'administrator' : auth()->user()->role;
    // Support staff can read orders but not change them, so they get no form that would end in a 403.
    $canFulfil = $staffRole !== 'support';
    $customer = $order->user && $order->user->role === 'customer' && ! $order->user->is_admin && in_array($staffRole, ['administrator','manager','support'], true) ? $order->user : null;
    $phoneDigits = preg_replace('/\D+/', '', (string) $order->address?->phone);
    // wa.me needs the country code; Indian mobile numbers are stored as 10 digits.
    $whatsappNumber = strlen($phoneDigits) === 10 ? '91'.$phoneDigits : (strlen($phoneDigits) === 12 && str_starts_with($phoneDigits, '91') ? $phoneDigits : null);
